package com.coxdrycalc;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(CoxDryCalcConfig.GROUP)
public interface CoxDryCalcConfig extends Config
{
    String GROUP = "coxdrycalc";

    enum ResetOn
    {
        MY_PURPLE,
        ANY_PURPLE
    }

    enum OverlayMode
    {
        IN_COX,
        ALWAYS,
        NEVER
    }

    @ConfigSection(
            name = "Current streak",
            description = "Edit these if you were already dry before installing the plugin",
            position = 0
    )
    String streakSection = "streak";

    @ConfigItem(
            keyName = "raidsSincePurple",
            name = "Regular: raids",
            description = "Completed regular raids since your last regular purple",
            section = streakSection,
            position = 0
    )
    default int raidsSincePurple()
    {
        return 0;
    }

    @ConfigItem(
            keyName = "pointsSincePurple",
            name = "Regular: points",
            description = "Personal points earned in regular raids since your last regular purple",
            section = streakSection,
            position = 1
    )
    default int pointsSincePurple()
    {
        return 0;
    }

    @ConfigItem(
            keyName = "cmRaidsSincePurple",
            name = "CM: raids",
            description = "Completed Challenge Mode raids since your last CM purple",
            section = streakSection,
            position = 2
    )
    default int cmRaidsSincePurple()
    {
        return 0;
    }

    @ConfigItem(
            keyName = "cmPointsSincePurple",
            name = "CM: points",
            description = "Personal points earned in Challenge Mode since your last CM purple",
            section = streakSection,
            position = 3
    )
    default int cmPointsSincePurple()
    {
        return 0;
    }

    @ConfigItem(
            keyName = "allRaidsSincePurple",
            name = "Combined: raids",
            description = "Completed raids of either mode since your last purple",
            section = streakSection,
            position = 4
    )
    default int allRaidsSincePurple()
    {
        return 0;
    }

    @ConfigItem(
            keyName = "allPointsSincePurple",
            name = "Combined: points",
            description = "Personal points earned in either mode since your last purple",
            section = streakSection,
            position = 5
    )
    default int allPointsSincePurple()
    {
        return 0;
    }

    @ConfigItem(
            keyName = "resetOn",
            name = "Reset streak on",
            description = "Reset only when you get a purple, or when anyone in your team does",
            position = 1
    )
    default ResetOn resetOn()
    {
        return ResetOn.MY_PURPLE;
    }

    @ConfigItem(
            keyName = "resetAllModes",
            name = "Purple resets every mode",
            description = "A purple in either mode resets the Regular, CM and combined streaks. Turn off to reset only the mode you got it in, plus combined.",
            position = 2
    )
    default boolean resetAllModes()
    {
        return true;
    }

    @ConfigItem(
            keyName = "overlayMode",
            name = "Show overlay",
            description = "When to show the dry calc overlay",
            position = 3
    )
    default OverlayMode overlayMode()
    {
        return OverlayMode.IN_COX;
    }

    @ConfigItem(
            keyName = "hideDuringRaid",
            name = "Hide overlay during raid",
            description = "Hide the overlay from \"The raid has begun!\" until the raid is complete",
            position = 4
    )
    default boolean hideDuringRaid()
    {
        return true;
    }

    @ConfigItem(
            keyName = "chatSummary",
            name = "Chat summary after raid",
            description = "Post your current dry streak in chat after each completed raid",
            position = 5
    )
    default boolean chatSummary()
    {
        return true;
    }

    @ConfigItem(
            keyName = "showPanel",
            name = "Show side panel",
            description = "Add a CoX Dry Calc button to the RuneLite sidebar with your stats and recent purples",
            position = 6
    )
    default boolean showPanel()
    {
        return true;
    }

    @ConfigItem(
            keyName = "logRaids",
            name = "Log raids to CSV",
            description = "Write every completed raid to cox-raids.csv, which opens in Excel. Type ::coxexport to save a copy anywhere.",
            position = 7
    )
    default boolean logRaids()
    {
        return true;
    }

    @ConfigSection(
            name = "Google Sheets",
            description = "Add each raid to your own Google Sheet. See the plugin README for the one-time setup.",
            position = 8
    )
    String sheetsSection = "sheets";

    @ConfigItem(
            keyName = "sheetsSync",
            name = "Send raids to Google Sheets",
            description = "Post each completed raid to your Google Apps Script web app. Teammates' names are not sent, only the items they got. Type ::coxsheetsync to upload raids logged before you turned this on.",
            warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
            section = sheetsSection,
            position = 0
    )
    default boolean sheetsSync()
    {
        return false;
    }

    @ConfigItem(
            keyName = "sheetsUrl",
            name = "Web app URL",
            description = "The https://script.google.com/macros/s/.../exec URL from deploying the script",
            secret = true,
            section = sheetsSection,
            position = 1
    )
    default String sheetsUrl()
    {
        return "";
    }
}

package com.coxdrycalc;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

class CoxDryCalcOverlay extends OverlayPanel
{
    private static final Color PURPLE = new Color(0xEF, 0x20, 0xFF);
    private static final Color CM_ORANGE = new Color(0xFB, 0x92, 0x3C);
    private static final Color COMBINED_TEAL = new Color(0x2D, 0xD4, 0xBF);
    private static final Color LABEL = new Color(0xC8, 0xC8, 0xC8);
    private static final Color DRY = new Color(0xFF, 0xB0, 0x40);
    private static final Color VERY_DRY = new Color(0xFF, 0x50, 0x50);
    // wide enough for the longest purple name
    private static final int WIDTH = 190;
    private static final RaidMode[] ORDER = {RaidMode.COMBINED, RaidMode.REGULAR, RaidMode.CM};

    private final CoxDryCalcPlugin plugin;
    private final CoxDryCalcConfig config;

    @Inject
    CoxDryCalcOverlay(CoxDryCalcPlugin plugin, CoxDryCalcConfig config)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        CoxDryCalcConfig.OverlayMode mode = config.overlayMode();
        if (mode == CoxDryCalcConfig.OverlayMode.NEVER
                || (mode == CoxDryCalcConfig.OverlayMode.IN_COX && !plugin.isInCox())
                || (config.hideDuringRaid() && plugin.isRaidInProgress()))
        {
            return null;
        }

        panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
        panelComponent.getChildren().add(TitleComponent.builder()
                .text("CoX Dry Calc")
                .color(PURPLE)
                .build());

        // show every mode, the cm varbit is also set in scaled regular raids
        for (RaidMode m : ORDER)
        {
            addMode(plugin.getStats(m));
        }
        return super.render(graphics);
    }

    private void addMode(ModeStats s)
    {
        if (s == null)
        {
            return;
        }
        List<LayoutableRenderableEntity> lines = panelComponent.getChildren();
        lines.add(LineComponent.builder()
                .left(s.mode == RaidMode.COMBINED ? "Both modes" : s.mode.getLabel())
                .leftColor(color(s.mode))
                .right(QuantityFormatter.formatNumber(s.raids) + (s.raids == 1 ? " raid" : " raids"))
                .rightColor(Color.WHITE)
                .build());
        lines.add(LineComponent.builder()
                .left("  Points")
                .leftColor(LABEL)
                .right(QuantityFormatter.formatNumber(s.points))
                .build());
        double chance = s.wouldHaveOne();
        lines.add(LineComponent.builder()
                .left("  Would have one")
                .leftColor(LABEL)
                .right(String.format("%.1f%%", 100 * chance))
                .rightColor(chance >= 0.75 ? VERY_DRY : chance >= 0.5 ? DRY : Color.WHITE)
                .build());
        if (!s.lastPurple.isEmpty())
        {
            lines.add(LineComponent.builder()
                    .left("  Last")
                    .leftColor(LABEL)
                    .right(s.lastPurple)
                    .rightColor(PURPLE)
                    .build());
        }
    }

    private static Color color(RaidMode mode)
    {
        switch (mode)
        {
            case CM:
                return CM_ORANGE;
            case COMBINED:
                return COMBINED_TEAL;
            default:
                return PURPLE;
        }
    }
}

package com.coxdrycalc;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.QuantityFormatter;

class CoxDryCalcPanel extends PluginPanel
{
    private static final Color PURPLE = new Color(0xC0, 0x84, 0xFC);
    private static final Color CM_ORANGE = new Color(0xFB, 0x92, 0x3C);
    private static final Color COMBINED_TEAL = new Color(0x2D, 0xD4, 0xBF);
    private static final int RECENT = 5;

    private final Map<RaidMode, ModeCard> cards = new EnumMap<>(RaidMode.class);

    CoxDryCalcPanel(Runnable onExport)
    {
        super(false);
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(10, 10, 10, 10));

        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel title = new JLabel("CoX Dry Calc");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(PURPLE);
        title.setAlignmentX(LEFT_ALIGNMENT);
        content.add(title);

        JLabel sub = new JLabel("<html>Your purples against the drop rate, from every raid this plugin has logged.</html>");
        sub.setFont(FontManager.getRunescapeSmallFont());
        sub.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        sub.setBorder(new EmptyBorder(2, 0, 10, 0));
        sub.setAlignmentX(LEFT_ALIGNMENT);
        content.add(sub);

        for (RaidMode mode : new RaidMode[]{RaidMode.COMBINED, RaidMode.REGULAR, RaidMode.CM})
        {
            ModeCard card = new ModeCard(mode);
            card.setAlignmentX(LEFT_ALIGNMENT);
            cards.put(mode, card);
            content.add(card);
        }

        JButton export = new JButton("Export raid log (CSV)");
        export.setToolTipText("Save cox-raids.csv to open in Excel or Google Sheets");
        export.setFocusPainted(false);
        export.addActionListener(e -> onExport.run());
        export.setAlignmentX(LEFT_ALIGNMENT);

        JPanel bottom = new JPanel(new BorderLayout());
        bottom.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bottom.setBorder(new EmptyBorder(4, 0, 0, 0));
        bottom.add(export, BorderLayout.CENTER);
        bottom.setAlignmentX(LEFT_ALIGNMENT);
        content.add(bottom);

        add(content, BorderLayout.NORTH);
    }

    // call on the swing thread, pass copies of the stats
    void update(Map<RaidMode, ModeStats> stats)
    {
        stats.forEach((mode, s) -> cards.get(mode).update(s));
        revalidate();
        repaint();
    }

    private static class ModeCard extends JPanel
    {
        private final JLabel raids = value();
        private final JLabel points = value();
        private final JLabel purples = value();
        private final JLabel expected = value();
        private final JLabel luck = value();
        private final JLabel perPurple = value();
        private final JLabel dryRaids = value();
        private final JLabel dryPoints = value();
        private final JLabel wouldHave = value();
        private final JPanel recent = new JPanel();
        private final JPanel sizes = new JPanel(new GridBagLayout());

        ModeCard(RaidMode mode)
        {
            setLayout(new BorderLayout());
            setBackground(ColorScheme.DARKER_GRAY_COLOR);
            setBorder(BorderFactory.createCompoundBorder(
                    new EmptyBorder(0, 0, 10, 0),
                    BorderFactory.createCompoundBorder(
                            BorderFactory.createMatteBorder(0, 3, 0, 0, color(mode)),
                            new EmptyBorder(8, 8, 8, 8))));

            JLabel header = new JLabel(mode == RaidMode.CM ? "Challenge Mode"
                    : mode == RaidMode.COMBINED ? "Both modes" : "Regular");
            header.setFont(FontManager.getRunescapeBoldFont());
            header.setForeground(color(mode));
            header.setBorder(new EmptyBorder(0, 0, 6, 0));
            add(header, BorderLayout.NORTH);

            JPanel grid = new JPanel(new GridBagLayout());
            grid.setOpaque(false);
            int row = 0;
            row = section(grid, row, "Current dry streak");
            row = line(grid, row, "Raids", dryRaids);
            row = line(grid, row, "Points", dryPoints);
            row = line(grid, row, "Would have one", wouldHave);
            row = section(grid, row, "All logged raids");
            row = line(grid, row, "Raids", raids);
            row = line(grid, row, "Your points", points);
            row = line(grid, row, "Your purples", purples);
            row = line(grid, row, "Expected purples", expected);
            row = line(grid, row, "Luck", luck);
            row = line(grid, row, "Points per purple", perPurple);
            section(grid, row, "By team size");

            sizes.setOpaque(false);
            JPanel recentHeader = new JPanel(new GridBagLayout());
            recentHeader.setOpaque(false);
            section(recentHeader, 1, "Recent purples");
            recent.setLayout(new BoxLayout(recent, BoxLayout.Y_AXIS));
            recent.setOpaque(false);

            JPanel body = new JPanel();
            body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
            body.setOpaque(false);
            for (JPanel part : new JPanel[]{grid, sizes, recentHeader, recent})
            {
                part.setAlignmentX(LEFT_ALIGNMENT);
                body.add(part);
            }
            add(body, BorderLayout.CENTER);
        }

        void update(ModeStats s)
        {
            dryRaids.setText(QuantityFormatter.formatNumber(s.raids));
            dryPoints.setText(QuantityFormatter.formatNumber(s.points));
            wouldHave.setText(String.format("%.1f%%", 100 * s.wouldHaveOne()));
            raids.setText(QuantityFormatter.formatNumber(s.totalRaids));
            points.setText(QuantityFormatter.formatNumber(s.totalPoints));
            purples.setText(Integer.toString(s.totalPurples));
            expected.setText(String.format("%.2f", s.expectedPurples));
            if (s.expectedPurples > 0)
            {
                double l = s.totalPurples / s.expectedPurples;
                luck.setText(String.format("%.2fx", l));
                luck.setForeground(l >= 1 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_ERROR_COLOR);
            }
            else
            {
                luck.setText("-");
                luck.setForeground(Color.WHITE);
            }
            perPurple.setText(s.totalPurples > 0
                    ? QuantityFormatter.quantityToStackSize(s.totalPoints / s.totalPurples)
                    : "None yet");

            sizes.removeAll();
            if (s.bySize.isEmpty())
            {
                addCell(sizes, small("No raids logged yet.", ColorScheme.LIGHT_GRAY_COLOR), 0, 0, 4, GridBagConstraints.WEST);
            }
            else
            {
                String[] head = {"Size", "Raids", "Purples", "Luck"};
                for (int i = 0; i < head.length; i++)
                {
                    addCell(sizes, small(head[i], ColorScheme.MEDIUM_GRAY_COLOR), i, 0, 1,
                            i == 0 ? GridBagConstraints.WEST : GridBagConstraints.EAST);
                }
                int r = 1;
                for (Map.Entry<Integer, ModeStats.SizeStats> e : s.bySize.entrySet())
                {
                    ModeStats.SizeStats z = e.getValue();
                    addCell(sizes, small(sizeName(e.getKey()), Color.WHITE), 0, r, 1, GridBagConstraints.WEST);
                    addCell(sizes, small(QuantityFormatter.formatNumber(z.raids), Color.WHITE), 1, r, 1, GridBagConstraints.EAST);
                    addCell(sizes, small(Integer.toString(z.purples), z.purples > 0 ? PURPLE : Color.WHITE), 2, r, 1, GridBagConstraints.EAST);
                    String l = z.expected > 0 ? String.format("%.2fx", z.purples / z.expected) : "-";
                    Color lc = z.expected <= 0 ? Color.WHITE
                            : z.purples / z.expected >= 1 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_ERROR_COLOR;
                    addCell(sizes, small(l, lc), 3, r, 1, GridBagConstraints.EAST);
                    r++;
                }
            }

            recent.removeAll();
            List<ModeStats.Purple> h = s.history;
            if (h.isEmpty())
            {
                recent.add(small("None yet. Good luck.", ColorScheme.LIGHT_GRAY_COLOR));
            }
            for (int i = h.size() - 1; i >= Math.max(0, h.size() - RECENT); i--)
            {
                ModeStats.Purple p = h.get(i);
                JLabel item = new JLabel(p.item);
                item.setFont(FontManager.getRunescapeSmallFont());
                item.setForeground(PURPLE);
                recent.add(item);
                recent.add(small(p.date + " · " + QuantityFormatter.formatNumber(p.raids)
                        + (p.raids == 1 ? " raid · " : " raids · ")
                        + QuantityFormatter.quantityToStackSize(p.points) + " pts", ColorScheme.LIGHT_GRAY_COLOR));
            }
        }

        private static Color color(RaidMode mode)
        {
            switch (mode)
            {
                case CM:
                    return CM_ORANGE;
                case COMBINED:
                    return COMBINED_TEAL;
                default:
                    return PURPLE;
            }
        }

        private static String sizeName(int size)
        {
            switch (size)
            {
                case 1:
                    return "Solo";
                case 2:
                    return "Duo";
                case 3:
                    return "Trio";
                default:
                    return size + "-man";
            }
        }

        private static void addCell(JPanel table, JLabel label, int x, int y, int width, int anchor)
        {
            GridBagConstraints c = new GridBagConstraints();
            c.gridx = x;
            c.gridy = y;
            c.gridwidth = width;
            c.weightx = x == 0 ? 1 : 0;
            c.anchor = anchor;
            c.insets = new Insets(0, x == 0 ? 0 : 10, 0, 0);
            table.add(label, c);
        }

        private static JLabel value()
        {
            JLabel l = new JLabel("0");
            l.setFont(FontManager.getRunescapeSmallFont());
            l.setForeground(Color.WHITE);
            l.setHorizontalAlignment(SwingConstants.RIGHT);
            return l;
        }

        private static JLabel small(String text, Color color)
        {
            JLabel l = new JLabel(text);
            l.setFont(FontManager.getRunescapeSmallFont());
            l.setForeground(color);
            l.setBorder(new EmptyBorder(0, 0, 3, 0));
            return l;
        }

        private static int section(JPanel grid, int row, String text)
        {
            JLabel l = new JLabel(text.toUpperCase());
            l.setFont(FontManager.getRunescapeSmallFont());
            l.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
            GridBagConstraints c = new GridBagConstraints();
            c.gridx = 0;
            c.gridy = row;
            c.gridwidth = 2;
            c.anchor = GridBagConstraints.WEST;
            c.insets = new Insets(row == 0 ? 0 : 6, 0, 2, 0);
            grid.add(l, c);
            return row + 1;
        }

        private static int line(JPanel grid, int row, String label, JLabel value)
        {
            JLabel l = new JLabel(label);
            l.setFont(FontManager.getRunescapeSmallFont());
            l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            GridBagConstraints c = new GridBagConstraints();
            c.gridx = 0;
            c.gridy = row;
            c.weightx = 1;
            c.anchor = GridBagConstraints.WEST;
            grid.add(l, c);
            c = new GridBagConstraints();
            c.gridx = 1;
            c.gridy = row;
            c.anchor = GridBagConstraints.EAST;
            grid.add(value, c);
            return row + 1;
        }
    }
}

